from itertools import combinations


def propagate_alldifferent(domains):
    domains = [set(d) for d in domains]
    changed = True
    while changed:
        changed = False
        count = len(domains)
        for size in range(1, count + 1):
            for group in combinations(range(count), size):
                union = set()
                for i in group:
                    union |= domains[i]
                if len(union) < size:
                    return None
                if len(union) == size:
                    for j in range(count):
                        if j not in group and domains[j] & union:
                            domains[j] -= union
                            changed = True
        if any(not domain for domain in domains):
            return None
    return domains
